package vn.edu.hcmute.bookstore_24110202.controller; import jakarta.servlet.annotation.*; import jakarta.servlet.http.*; import java.io.*; @WebServlet("/logout") public class LogoutController_24110202 extends HttpServlet {protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{if(q.getSession(false)!=null)q.getSession(false).invalidate();p.sendRedirect(q.getContextPath()+"/login");}}
